/bin/zsh -lc "ruby -ryaml -e '
c=YAML.load_file(\"output/correction.yaml\"); abort \"bad lab\" unless c[\"lab_inline\"]==File.read(\"candidate/lab.conf\");
expected={}; Dir[\"candidate/r*.startup\"].each{|f| d=File.basename(f,\".startup\"); expected[d]=File.readlines(f).grep(/"'^ip route add (?!default)/).map{|l| a=l.split; [a[3], a[5], "eth"+(a[7] || "").sub("eth", "")] rescue nil}; c["test"]["kernel_routes"].each{|d,rs| actual=rs.map{|p,n| [p,n[0],n[1]]}; desired=File.readlines("candidate/#{d}.startup").grep(/''^ip route add (?!default)/).map{|l| x=l.split; [x[3],x[5], x[7] || ({"r1"=>{"10.2.2.0/24"=>"eth1","10.3.3.0/24"=>"eth2","10.4.4.0/24"=>"eth1","10.5.5.0/24"=>"eth1","10.255.24.0/30"=>"eth1","10.255.34.0/30"=>"eth2","10.255.45.0/30"=>"eth1"},"r2"=>{"10.1.1.0/24"=>"eth1","10.3.3.0/24"=>"eth1","10.4.4.0/24"=>"eth2","10.5.5.0/24"=>"eth2","10.255.13.0/30"=>"eth1","10.255.34.0/30"=>"eth2","10.255.45.0/30"=>"eth2"},"r3"=>{"10.1.1.0/24"=>"eth1","10.2.2.0/24"=>"eth1","10.4.4.0/24"=>"eth2","10.5.5.0/24"=>"eth2","10.255.12.0/30"=>"eth1","10.255.24.0/30"=>"eth2","10.255.45.0/30"=>"eth2"},"r4"=>{},"r5"=>{}}[d][x[3]])]}; abort "route mismatch #{d}: #{actual} != #{desired}" unless actual==desired}; puts "YAML and routes OK"'"' && git diff --check -- output/correction.yaml && git status --short -- output/correction.yaml"

